from math import comb

def calculate_ratio(n):
    if n < 4:
        return float('inf') # Or handle appropriately, though G must support K4
    g_n = comb(n, 4)
    f_n = comb(n, 3)
    if f_n == 0: # Should not happen if n >= 3
        return float('inf')
    return (g_n**3) / (f_n**4)

# Checking K4 through K8
results = {}
for n in range(4, 9):
    results[n] = calculate_ratio(n)

print("n=4: ", results[4])
print("n=5: ", results[5])
print("n=6: ", results[6])
print("n=7: ", results[7])
print("n=8: ", results[8])

import math

def nCr(n, r):
    if r < 0 or r > n:
        return 0
    return math.comb(n, r)

def get_g_max(f):
    # Kruskal-Katona representation of f as a sum of nCr(n_i, i)
    # f = nCr(n3, 3) + nCr(n2, 2) + nCr(n1, 1)
    n3 = 0
    while nCr(n3 + 1, 3) <= f:
        n3 += 1

    f1 = f - nCr(n3, 3)
    n2 = 0
    while nCr(n2 + 1, 2) <= f1:
        n2 += 1

    f2 = f1 - nCr(n2, 2)
    n1 = f2 # since nCr(n1, 1) = n1

    return nCr(n3, 4) + nCr(n2, 3) + nCr(n1, 2)

max_ratio = 0
for f in range(1, 1000):
    g = get_g_max(f)
    ratio = (g**3) / (f**4)
    if ratio > max_ratio:
        max_ratio = ratio

print(f"Max ratio for f < 1000: {max_ratio}")

for n in range(4, 101):
    f = nCr(n, 3)
    g = nCr(n, 4)
    ratio = (g**3) / (f**4)
    if ratio > max_ratio:
        max_ratio = ratio
    if n == 100:
        print(f"Ratio for n=100: {ratio}")

